package com.andye.warmod.silo.network;import com.andye.warmod.WarMod;import java.util.UUID;import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;public record ServerboundSiloLaunchPayload(int menuId,BlockPos centre,UUID siloId)implements CustomPacketPayload{public static final Type<ServerboundSiloLaunchPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"silo_launch"));public static final StreamCodec<RegistryFriendlyByteBuf,ServerboundSiloLaunchPayload> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeVarInt(p.menuId);b.writeBlockPos(p.centre);b.writeUUID(p.siloId);},b->new ServerboundSiloLaunchPayload(b.readVarInt(),b.readBlockPos(),b.readUUID()));@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}